#!/usr/bin/env bash
#
# BitFinite single-coin flavor for the Stack Wallet fork.
# Drop into scripts/app_config/configure_bitfinite.sh (mirrors configure_campfire.sh).
# Usage (from the fork root, via scripts/build_app.sh which sets APP_PROJECT_ROOT_DIR):
#   scripts/app_config/configure_bitfinite.sh <platform>

set -x -e

APP_BUILD_PLATFORM=$1

export NEW_NAME="BitFinite"
# Overridable so a test build can install BESIDE a real wallet instead of over it.
# build.gradle is GENERATED by build_app.sh, so an applicationIdSuffix added there
# is erased on the next build — the id has to come from here.
#
#   BFX_APP_ID=org.bitfinitechain.wallet.debug scripts/build-android-docker.sh
#
# Without it a sideloaded debug APK targets the user's installed wallet: Android
# refuses it on the version code, and the usual workaround is `adb uninstall`,
# which deletes the wallet and its keys. Hit on a device carrying a real 1.4.1.
export NEW_APP_ID="${BFX_APP_ID:-org.bitfinitechain.wallet}"        # matches the existing Capacitor appId
export NEW_APP_ID_CAMEL="${BFX_APP_ID:-org.bitfinitechain.wallet}"
export NEW_APP_ID_SNAKE="${BFX_APP_ID:-org.bitfinitechain.wallet}"
export NEW_BASIC_NAME="bitfinite"

NEW_PUBSPEC_NAME="bitfinite"
PUBSPEC_FILE="${APP_PROJECT_ROOT_DIR}/pubspec.yaml"

# String replacements.
if [[ "$(uname)" == 'Darwin' ]]; then
  sed -i '' "s/name: PLACEHOLDER/name: ${NEW_PUBSPEC_NAME}/g" "${PUBSPEC_FILE}"
  sed -i '' "s/description: PLACEHOLDER/description: ${NEW_NAME}/g" "${PUBSPEC_FILE}"
else
  sed -i "s/name: PLACEHOLDER/name: ${NEW_PUBSPEC_NAME}/g" "${PUBSPEC_FILE}"
  sed -i "s/description: PLACEHOLDER/description: ${NEW_NAME}/g" "${PUBSPEC_FILE}"
fi

# Drop assets/gif/ from THIS flavour only.
#
# The directory holds two upstream mascot animations, 13 MB of an 80 MB APK,
# and neither can be reached in a BitFinite build:
#
#   monero-chan-dance.gif  2.4 MB   shown by the churning views. Churning is a
#                                   Monero feature and this flavour ships five
#                                   coins, none of them Monero.
#   stacy_onion.gif       10.6 MB   shown by the one-time Tor dialog. All three
#                                   of its call sites are commented out.
#
# Every release we have published is Android, where that is 16% of what a user
# downloads over mobile data for something they can never see.
#
# Scoped here rather than in the shared template because Stack Wallet, Stack
# Duo and Campfire all ship Monero and genuinely use these. The files stay in
# the repo for them. If churning or the Tor dialog is ever turned on for
# BitFinite, delete this block in the same commit, or the widget will fail at
# runtime looking for an asset that was not bundled.
if [[ "$(uname)" == 'Darwin' ]]; then
  sed -i '' "/^    - assets\/gif\/$/d" "${PUBSPEC_FILE}"
else
  sed -i "/^    - assets\/gif\/$/d" "${PUBSPEC_FILE}"
fi

# Coin/feature flags. BFX is pure-Dart (coinlib) like BCH — it needs NO native
# crypto .so (unlike FIRO/EPIC/MONERO). If process_pubspec_deps.dart / gen_interfaces.dart
# require an explicit token, add "BITFINITE" to their known-coins list (see POC.md).
# Passing only TOR here keeps the build lean; adjust once the flag is registered.
dart "${APP_PROJECT_ROOT_DIR}/tool/process_pubspec_deps.dart" \
      "${PUBSPEC_FILE}" \
      TOR

dart "${APP_PROJECT_ROOT_DIR}/tool/gen_interfaces.dart" \
      "${APP_PROJECT_ROOT_DIR}/tool/wl_templates" \
      "${APP_PROJECT_ROOT_DIR}/lib/wl_gen/generated" \
      TOR

export INCLUDE_EPIC_SO="OFF"
export INCLUDE_MWC_SO="OFF"

pushd "${APP_PROJECT_ROOT_DIR}"
BUILT_COMMIT_HASH=$(git log -1 --pretty=format:"%H")
popd

APP_CONFIG_DART_FILE="${APP_PROJECT_ROOT_DIR}/lib/app_config.g.dart"
rm -f "$APP_CONFIG_DART_FILE"
cat << EOF > "$APP_CONFIG_DART_FILE"
// GENERATED CODE - DO NOT MODIFY BY HAND

part of 'app_config.dart';

const _prefix = "BitFinite";
const _separator = "";
const _suffix = "";
const _emptyWalletsMessage =
    "Create your BitFinite wallet to get started.";
const _appDataDirName = "bitfinite";
const _shortDescriptionText = "Your keys. Your coins. Your BitFinite.";
const _commitHash = "$BUILT_COMMIT_HASH";

const _mwebdExeHash = "";

const Set<AppFeature> _features = {
  AppFeature.tor,
  // Enables the Appearance settings entry + installs the dark theme, so users
  // can switch between the BitFinite light/dark themes (and system-brightness).
  AppFeature.themeSelection,
};

// PoC: no in-app logo asset yet (app_icon.dart null-checks this and falls back).
// TODO(bfx): add assets/in_app_logo_icons/bitfinite-icon_light/dark.svg from Brandkit.
const ({String light, String dark})? _appIconAsset = null;

final List<CryptoCurrency> _supportedCoins = List.unmodifiable([
  Bitfinite(CryptoCurrencyNetwork.main),
  // Pepecoin, the first coin added beyond BFX. It rides two public Electrum
  // servers we do not run (electrum.pepeblocks.com, electrum.pepe.tips) — the
  // whole of Pepecoin's public Electrum infrastructure, since the third
  // published host no longer resolves.
  Pepecoin(CryptoCurrencyNetwork.main),
  // Bellscoin has no Electrum server anywhere (the chain is ~365 GB); it
  // rides Nintondo's esplora HTTP API through EsploraElectrumXClient.
  Bellscoin(CryptoCurrencyNetwork.main),
  // Bitcoin and Dogecoin, so the wallet holds what people already own rather
  // than only what we issue. Both are inherited from upstream and needed no
  // new wallet code — only their default nodes moved, off Cypher Stack's
  // servers and onto public ones (see bitcoin.dart / dogecoin.dart).
  //
  // Neither is swappable or buyable in-app: those are separate features, and
  // both are still off.
  Bitcoin(CryptoCurrencyNetwork.main),
  Dogecoin(CryptoCurrencyNetwork.main),
]);

// BFX is not on exchanges; swap defaults are unused but the field is required.
final ({String from, String fromFuzzyNet, String to, String toFuzzyNet})
_swapDefaults = (
  from: "BTC",
  fromFuzzyNet: "btc",
  to: "BFX",
  toFuzzyNet: "bfx",
);

EOF
